    13→// TestSubagentAccumulation_Issue591 reproduces the issue #591 shape: multiple
    14→// subagent sessions end with uncommitted files that never overlap with a later
    15→// parent-session commit. The stale ENDED subagent sessions must be force-condensed
    16→// on that later commit so they do not accumulate and get re-processed forever.
    17→func TestSubagentAccumulation_Issue591(t *testing.T) {
    18→	t.Parallel()
    19→
    20→	env := NewFeatureBranchEnv(t)
    21→
    22→	type subagentInfo struct {
