    28→
    29→	parent := env.NewSession()
    30→	if err := env.SimulateUserPromptSubmit(parent.ID); err != nil {
    31→		t.Fatalf("SimulateUserPromptSubmit for parent failed: %v", err)
    32→	}
    33→	parent.TranscriptBuilder.AddUserMessage("Use subagents to investigate the work and then create the parent file.")
    34→
    35→	const numSubagents = 4
    36→	subagents := make([]subagentInfo, 0, numSubagents)
    37→
    38→	for i := 0; i < numSubagents; i++ {
    39→		sub := env.NewSession()
    40→		file := fmt.Sprintf("subagent_work_%d.go", i)
    41→		content := fmt.Sprintf("package main\n\nfunc SubagentWork%d() {}\n", i)
    42→
    43→		if err := env.SimulateUserPromptSubmit(sub.ID); err != nil {
    44→			t.Fatalf("SimulateUserPromptSubmit for subagent %d failed: %v", i, err)
    45→		}
    46→
