    48→		sub.CreateTranscript("Create "+file, []FileChange{
    49→			{Path: file, Content: content},
    50→		})
    51→
    52→		if err := env.SimulateStop(sub.ID, sub.TranscriptPath); err != nil {
    53→			t.Fatalf("SimulateStop for subagent %d failed: %v", i, err)
    54→		}
    55→		if err := env.SimulateSessionEnd(sub.ID); err != nil {
    56→			t.Fatalf("SimulateSessionEnd for subagent %d failed: %v", i, err)
    57→		}
    58→
    59→		state, err := env.GetSessionState(sub.ID)
    60→		if err != nil {
    61→			t.Fatalf("GetSessionState for subagent %d failed: %v", i, err)
    62→		}
    63→		if state == nil {
