    71→		}
    72→		if state.StepCount == 0 {
    73→			t.Fatalf("subagent %d StepCount should be > 0 before cleanup", i)
    74→		}
    75→		if state.FullyCondensed {
    76→			t.Fatalf("subagent %d should not be FullyCondensed before cleanup", i)
    77→		}
    78→
    79→		staleEndedAt := time.Now().Add(-2 * time.Hour)
    80→		state.EndedAt = &staleEndedAt
    81→		if err := env.WriteSessionState(sub.ID, state); err != nil {
    82→			t.Fatalf("WriteSessionState for subagent %d failed: %v", i, err)
    83→		}
    84→
    85→		taskToolUseID := fmt.Sprintf("toolu_parent_subagent_%d", i)
    86→		parent.TranscriptBuilder.AddTaskToolUse(taskToolUseID, "Create "+file)
    87→		parent.TranscriptBuilder.AddTaskToolResult(taskToolUseID, sub.ID)
    88→
