    99→	env.WriteFile(parentFile, parentContent)
   100→	parentToolUseID := parent.TranscriptBuilder.AddToolUse("mcp__acp__Write", parentFile, parentContent)
   101→	parent.TranscriptBuilder.AddToolResult(parentToolUseID)
   102→	parent.TranscriptBuilder.AddAssistantMessage("Done.")
   103→	if err := parent.TranscriptBuilder.WriteToFile(parent.TranscriptPath); err != nil {
   104→		t.Fatalf("failed to write parent transcript: %v", err)
   105→	}
   106→
   107→	if err := env.SimulateStop(parent.ID, parent.TranscriptPath); err != nil {
   108→		t.Fatalf("SimulateStop for parent failed: %v", err)
   109→	}
