   141→		t.Fatalf("SimulateUserPromptSubmit for follow-up session failed: %v", err)
   142→	}
   143→
   144→	followUpFile := "follow_up.go"
   145→	followUpContent := "package main\n\nfunc FollowUp() {}\n"
   146→	env.WriteFile(followUpFile, followUpContent)
   147→	followUp.CreateTranscript("Create "+followUpFile, []FileChange{
   148→		{Path: followUpFile, Content: followUpContent},
   149→	})
   150→	if err := env.SimulateStop(followUp.ID, followUp.TranscriptPath); err != nil {
   151→		t.Fatalf("SimulateStop for follow-up session failed: %v", err)
   152→	}
   153→
   154→	env.GitCommitWithShadowHooks("Follow-up commit", followUpFile)
   155→
   156→	for i, sub := range subagents {
   157→		state, err := env.GetSessionState(sub.SessionID)
   158→		if err != nil {
   159→			t.Fatalf("GetSessionState after follow-up commit for subagent %d failed: %v", i, err)
   160→		}
   161→		if state == nil {
   162→			t.Fatalf("subagent %d session state missing after follow-up commit", i)
   163→		}
   164→		if !state.FullyCondensed {
   165→			t.Fatalf("subagent %d should remain FullyCondensed after follow-up commit", i)
   166→		}
   167→		if state.StepCount != 0 {
   168→			t.Fatalf("subagent %d StepCount = %d after follow-up commit, want 0", i, state.StepCount)
   169→		}
   170→	}
   171→}
